export function getArticleBySlug(slug: string): HelpCenterArticle | undefined {
  return HELP_CENTER_ARTICLES.find((a) => a.slug === slug);
}

export function getArticleById(articleId: string): HelpCenterArticle | undefined {
  return HELP_CENTER_ARTICLES.find((a) => a.articleId === articleId);
}
